// Name returns the Python member name.
func (e ARNvramIndexType) Name() string { return aRNvramIndexTypeNames[e] }

// Valid reports whether e is a defined member.
func (e ARNvramIndexType) Valid() bool { _, ok := aRNvramIndexTypeNames[e]; return ok }

// ARNvramIndexTypeFromValueOK mirrors `ARNvramIndexType.from_value` without the UNKNOWN fallback.
func ARNvramIndexTypeFromValueOK(value any) (ARNvramIndexType, bool) {
	switch v := value.(type) {
	case ARNvramIndexType:
		return v, v.Valid()
	case *ARNvramIndexType:
		if v != nil {
			return *v, v.Valid()
		}
	}
	if vstr := converters.RawToStr(value); vstr != nil {
		if m := ARNvramIndexType(*vstr); m.Valid() {
			return m, true
		}
		if m, ok := aRNvramIndexTypeByName[strings.ToUpper(*vstr)]; ok {
			return m, true
		}
	}
	var zero ARNvramIndexType
	return zero, false
}

// ARNvramIndexTypeFromValue mirrors `ARNvramIndexType.from_value`: unresolved values map to ARNvramIndexTypeUnknown.
func ARNvramIndexTypeFromValue(value any) ARNvramIndexType {
	if m, ok := ARNvramIndexTypeFromValueOK(value); ok {
		return m
	}
	return ARNvramIndexTypeUnknown
}
